corrected_code:
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const { db } = require('../db');

async function processPreferenceStream() {
  while (true) {
    const res = await redis.xreadgroup('GROUP', 'pref-sync', 'worker-1', 'BLOCK', 2000, 'STREAMS', 'stream:user:preferences', '>');
    if (!res) continue;

    for (const [, events] of res) {
      for (const [id, kv] of events) {
        const { userId, actorId, smsOptOut, emailOptOut } = JSON.parse(kv[1]);
        if (userId !== actorId) {
          await redis.xack('stream:user:preferences', 'pref-sync', id);
          continue;
        }
        await db.query(
          'UPDATE user_communication_settings SET sms_opt_out = $1, email_opt_out = $2 WHERE user_id = $3',
          [smsOptOut, emailOptOut, userId]
        );
        await redis.xack('stream:user:preferences', 'pref-sync', id);
      }
    }
  }
}
